eapFlag_AC InstallMakeNewFail;					CTidyHeapFlag_AC InstallIncrementalFailer;	CTidyHeapFlag_AC InstallNewVerifyAction;	CTidyHeapFlag_AC InstallNewVerifyAllAction;	CTidyHeapFlag_AC InstallExemptUnknownBlocks;	CTidyHeapFlag_AC InstallGarbageIn;	CTidyHeapFlag_AC InstallNewBreakOnUnknownBlock;			 // Global Delete Actions	CTidyHeapFlag_AC InstallDeleteBreakOnUnknownBlock;	CTidyHeapFlag_AC InstallDeleteVerifyAction;	CTidyHeapFlag_AC InstallGarbageOut;	CTidyHeapFlag_AC InstallDeleteVerifyAllAction;			// flag set by tidyHeap director	CTidyHeapFlag_AC SettingsModifiedExternally;		protected:	virtual void SetSessionNameToDefault();				private:	virtual void Read( CTidyHeapFile_AC * inFile);	virtual void Write( CTidyHeapFile_AC * inFile);private:		char 			fSessionName[kNameSize];		long 			fNewFailCount;	unsigned long	fLastWriteSeconds;	};//----------------------------------------------------------------------------------------// Inlines//----------------------------------------------------------------------------------------inline const char* CTidyHeapSettings_AC::GetSessionName() const { 	return fSessionName; }inline void CTidyHeapSettings_AC::SetNewFailCount( long inCount ) { 	fNewFailCount = inCount; }inline long CTidyHeapSettings_AC::GetNewFailCount() const { 	return fNewFailCount; }#endif